from pathlib import Path
import sys
site=Path(sys.argv[1])/'site'
common='''<style id="xi-safe-common">:root{--xi-safe-top:env(safe-area-inset-top,0px);--xi-safe-right:env(safe-area-inset-right,0px);--xi-safe-bottom:env(safe-area-inset-bottom,0px);--xi-safe-left:env(safe-area-inset-left,0px);--xi-fallback-top:0px;--xi-fallback-bottom:0px;--xi-top:max(var(--xi-safe-top),var(--xi-fallback-top));--xi-bottom:max(var(--xi-safe-bottom),var(--xi-fallback-bottom));--xi-height:calc(100dvh - var(--xi-top) - var(--xi-bottom));--xi-width:calc(100vw - var(--xi-safe-left) - var(--xi-safe-right))}@media(orientation:portrait){html[data-xi-ios-standalone]{--xi-fallback-top:60px;--xi-fallback-bottom:24px}}body{box-sizing:border-box;padding:var(--xi-top) var(--xi-safe-right) var(--xi-bottom) var(--xi-safe-left);min-height:100dvh}button{overflow-wrap:anywhere}input,select{max-width:100%}</style><script>(()=>{if((/iPhone|iPad|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1))&&(navigator.standalone===true||matchMedia('(display-mode: standalone)').matches))document.documentElement.setAttribute('data-xi-ios-standalone','')})();</script>'''
styles={
'legacy': '''#app{width:100%;min-width:0}header{flex-wrap:wrap}header div{min-width:90px;overflow-wrap:anywhere}header button{min-width:44px;min-height:44px}header h1{overflow-wrap:anywhere}.battle-main,aside,.panel,.stat,.row>div{min-width:0;overflow-wrap:anywhere}.battle-title{flex-wrap:wrap}.battle-title>div{flex:1 1 100px}.battle-title button,.commands button,.tabs button{min-height:44px;min-width:0;white-space:normal}.status #remain{white-space:normal}.status{flex-wrap:wrap}.shop button{min-width:0;overflow-wrap:anywhere}.shop canvas{max-width:100%;height:auto}.field{display:flex;justify-content:center;align-items:center}#field{width:100%;height:auto;max-height:none;aspect-ratio:5/3;object-fit:fill}.techrow{flex-wrap:wrap}.techrow>div{min-width:0}.tabs{flex-wrap:wrap}dialog{max-width:min(450px,calc(var(--xi-width) - 24px));max-height:calc(var(--xi-height) - 24px);margin:auto;position:fixed;inset:var(--xi-top) var(--xi-safe-right) var(--xi-bottom) var(--xi-safe-left);overflow:auto;overscroll-behavior:contain}#toast{bottom:calc(18px + var(--xi-bottom));max-width:calc(var(--xi-width) - 24px)}#introSound{bottom:calc(12px + var(--xi-bottom))}@media(max-width:360px){header img{width:30px;height:30px}header div{flex:1 1 100px}header button{padding:6px}.hud{gap:3px}.stat b{font-size:17px}.stat small{font-size:9px}.shop{grid-template-columns:repeat(3,minmax(0,1fr))}.hero-banner h2{font-size:clamp(20px,7vw,40px)}}@media(orientation:landscape) and (max-height:540px){.battle-layout{grid-template-columns:minmax(0,1fr) minmax(170px,30%)}#field{width:min(100%,calc(max(120px,var(--xi-height) - 220px)*5/3))}aside{max-height:none;overflow:visible}}@media(orientation:landscape) and (max-width:560px){.battle-layout{grid-template-columns:1fr}#field{width:100%}}''',
'cubiq':'''#cubiqFinal{box-sizing:border-box;min-height:var(--xi-height);padding:0;overflow:visible;width:100%;min-width:0}#cubiqFinal .top{grid-template-columns:44px minmax(0,1fr) 44px;gap:6px;padding:8px 12px 4px}#cubiqFinal .title{min-width:0;overflow-wrap:anywhere;font-size:clamp(18px,5vw,25px)}#cubiqFinal .tools{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;padding:4px 12px 12px}#cubiqFinal .tools button{min-width:0;overflow-wrap:anywhere}#cubiqFinal .stage{flex:1 1 max(200px,calc(var(--xi-height) - 240px));min-height:180px}#cubiqFinal .overlay{position:fixed;inset:var(--xi-top) var(--xi-safe-right) var(--xi-bottom) var(--xi-safe-left);padding:12px;overflow:auto;overscroll-behavior:contain}#cubiqFinal .panel{max-height:calc(var(--xi-height) - 24px);min-width:0;overflow:auto;padding:16px;overflow-wrap:anywhere}#cubiqFinal .levels{grid-template-columns:repeat(4,minmax(0,1fr))}#cubiqFinal .levels button{min-width:0;padding:3px}#cubiqFinal .zoom{right:8px}#cubiqFinal .status{overflow-wrap:anywhere}@media(orientation:landscape) and (max-height:540px) and (min-width:561px){#cubiqFinal{max-width:100%;display:grid;grid-template-columns:minmax(0,1fr) minmax(140px,220px);grid-template-rows:auto auto auto minmax(50px,1fr) auto;gap:4px;padding:4px 8px}#cubiqFinal .stage{grid-area:1/1/6/2;min-height:max(180px,calc(var(--xi-height) - 8px))}#cubiqFinal .top,#cubiqFinal .hearts,#cubiqFinal .bar,#cubiqFinal .status,#cubiqFinal .tools{grid-column:2}#cubiqFinal .top{padding:0;gap:2px}#cubiqFinal .title{font-size:16px}#cubiqFinal .hearts{height:auto!important;font-size:22px}#cubiqFinal .tools{display:grid;grid-template-columns:1fr;padding:0;gap:4px}#cubiqFinal .tools button{min-height:44px!important}#cubiqFinal .tools b{display:inline;margin-right:6px;font-size:18px}#cubiqFinal .status{align-self:center;padding:2px}}''',
'block-nova':'''body{display:flex;align-items:center;justify-content:center}#game{box-sizing:border-box;min-width:0;width:min(100%,480px);padding:10px;overflow:visible;align-self:center}#board{width:min(100%,calc(max(220px,var(--xi-height) - 166px)*360/440));height:auto;aspect-ratio:360/440;margin:0 auto}#mode{min-width:0;text-align:center;overflow-wrap:anywhere;letter-spacing:1px}#score,#record{overflow-wrap:anywhere;font-size:clamp(34px,11vw,72px)}#record{font-size:18px}#hint{overflow-wrap:anywhere}#overlay{position:fixed;inset:var(--xi-top) var(--xi-safe-right) var(--xi-bottom) var(--xi-safe-left);overflow:auto;padding:12px;overscroll-behavior:contain}.panel{max-height:calc(var(--xi-height) - 24px);overflow:auto;padding:16px;overflow-wrap:anywhere}@media(orientation:landscape) and (max-height:540px) and (min-width:561px){#game{width:100%;max-width:800px;display:grid;grid-template-columns:minmax(0,1fr) minmax(140px,210px);grid-template-rows:auto auto auto auto auto 1fr;gap:4px 12px;padding:6px}#board{grid-area:1/1/7/2;width:min(100%,calc(max(180px,var(--xi-height) - 12px)*360/440));align-self:center}header,#record,#score,#combo,#progress,#hint{grid-column:2}#record{margin:2px 0 0}#score{font-size:clamp(32px,8vw,56px)}#hint{align-self:center}#combo{height:auto;min-height:19px}}'''
}
for game,css in styles.items():
 p=site/'games'/game/'index.html';s=p.read_text();tag=common+'<style id="xi-game-safe-layout">'+css+'</style>';assert 'xi-game-safe-layout' not in s;anchor='</head>' if '</head>' in s else '</style>';i=s.rfind(anchor);assert i>=0;p.write_text(s[:i]+tag+s[i:] if anchor=='</head>' else s[:i+len(anchor)]+tag+s[i+len(anchor):])
